#!/usr/bin/env bash
# Creates .env with fresh random local credentials. Never prints them.
set -euo pipefail
cd "$(dirname "$0")/.."
if [[ -f .env ]]; then
  echo ".env already exists, keeping it."
  exit 0
fi
rand() { python3 -c "import secrets,sys; print(secrets.token_hex(int(sys.argv[1])))" "$1"; }
umask 077
cat > .env <<ENV
# Generated by scripts/gen-env.sh. Local demo credentials only. Do not commit.
SECRET_KEY_BASE=$(rand 64)
POSTGRES_PASSWORD=$(rand 24)
REDIS_PASSWORD=$(rand 24)
BOT_WEBHOOK_SECRET=$(rand 24)
CHATWOOT_URL=http://localhost:3010
ADMIN_NAME=Recepción Ondaviva
ADMIN_EMAIL=recepcion@ondaviva.example
ADMIN_PASSWORD=Demo-$(rand 12)!
ENV
echo "Wrote .env (mode 600)."
